{"content": "1|import '../styles/globals.css';
2|import type { AppProps } from 'next/app';
3|import { AuthProvider } from '@tad/ui';
4|
5|import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
6|import { PersistQueryClientProvider } from '@tanstack/react-query-persist-client';
7|import { createSyncStoragePersister } from '@tanstack/query-sync-storage-persister';
8|import { Toaster } from 'sonner';
9|import { useAntigravity } from '@tad/ui';
10|import { useState, useEffect } from 'react';
11|import { logger } from '@tad/logging';
12|
13|
14|const PUBLIC_PAGES = [
15|  '/login',
16|  '/admin/login',
17|  '/advertiser/login',
18|  '/driver/login',
19|  '/driver/onboarding',
20|  '/advertiser/onboarding',
21|  '/check-in',
22|];
23|
24|function AppWrapper({ Component, pageProps, router }: AppProps) {
25|  const isPublic =
26|    PUBLIC_PAGES.includes(router.pathname) || router.pathname.startsWith('/p');
27|
28|  // Initialize Logger
29|  useEffect(() => {
30|    if (logger) {
31|      logger.info('App', `Navigated to ${router.pathname}`);
32|    }
33|  }, [router.pathname]);
34|
35|  // Initialize Realtime Sync Hook
36|  useAntigravity(!isPublic);
37|
38|  return (
39|    <AuthProvider>
40|      <div className="font-sans antialiased">
41|        <Component {...pageProps} />
42|      </div>
43|    </AuthProvider>
44|  );
45|}
46|
47|export default function App(props: AppProps) {
48|  // Ensure QueryClient is only created once on the client
49|  const [queryClient] = useState(() => new QueryClient({
50|    defaultOptions: {
51|      queries: {
52|        gcTime: 1000 * 60 * 60 * 24, // 24 hours
53|        staleTime: 1000 * 60 * 5, // 5 minutes cache
54|        retry: 3,
55|        refetchOnWindowFocus: true,
56|      },
57|    },
58|  }));
59|
60|  const persister = typeof window !== 'undefined' ? createSyncStoragePersister({
61|    storage: window.localStorage,
62|  }) : undefined;
63|
64|  if (!persister) {
65|    return (
66|      <QueryClientProvider client={queryClient}>
67|        <AppWrapper {...props} />
68|        <Toaster richColors position="top-right" theme="dark" />
69|      </QueryClientProvider>
70|    );
71|  }
72|
73|  return (
74|    <PersistQueryClientProvider 
75|      client={queryClient} 
76|      persistOptions={{ persister }}
77|    >
78|      <AppWrapper {...props} />
79|      <Toaster richColors position="top-right" theme="dark" />
80|    </PersistQueryClientProvider>
81|  );
82|}
