{"content": "1|import { useEffect, useRef } from 'react';
2|import { supabase } from '@tad/services';
3|import { usePaymentStore } from '../store/usePaymentStore';
4|import { openDB } from 'idb';
5|
6|const DB_NAME = 'tad_telemetry_db';
7|const STORE_NAME = 'gps_buffer';
8|const POSTGREST_RPC_URL = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/rpc/bulk_insert_telemetry`;
9|const ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
10|
11|/**
12| * @deprecated v12.1.3 — usar `useTelemetry.ts` como hook único canónico.
13| * Mantenido temporalmente por compatibilidad histórica. NO MONTAR en código
14| * nuevo. La razón de la deprecación es:
15| *  - Duplica `geolocation.watchPosition` con `useTelemetry`, violando regla
16| *    #4 (un único worker GPS por dispositivo) y duplicando consumo de batería.
17| *  - Cada activación sumaba dos canales `navigator.geolocation` independientes.
18| *
19| * Si necesitas telemetría offline-first + realtime + kill-switch, importa:
20| *     import { useTelemetry } from '../hooks/useTelemetry';
21| *
22| * Si necesitas el comportamiento legacy (canal realtime broadcast vía Supabase),
23| * refactorízalo al módulo `services/telemetry/` para que `useTelemetry` lo use.
24| */
25|const GRACE_PERIOD_MS = 48 * 60 * 60 * 1000; // 48 hours
26|const SUBSCRIPTION_CACHE_KEY = 'TAD_SUBSCRIPTION_STATUS';
27|const SUBSCRIPTION_EXPIRY_KEY = 'TAD_SUBSCRIPTION_EXPIRY';
28|
29|export const useBackgroundTelemetry = (driverId: string) => {
30|  const lastSyncTime = useRef<number>(0);
31|  const lastLivePingTime = useRef<number>(0);
32|  const watchIdRef = useRef<number | null>(null);
33|  const suspendedRef = useRef<boolean>(false);
34|  const { setLock } = usePaymentStore();
35|
36|  useEffect(() => {
37|    if (!driverId) return;
38|    if (!('geolocation' in navigator)) return;
39|
40|    // IDB Setup
41|    const dbPromise = openDB(DB_NAME, 1, {
42|      upgrade(db) {
43|        if (!db.objectStoreNames.contains(STORE_NAME)) {
44|          db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
45|        }
46|      },
47|    });
48|
49|    // Check for cached killSwitch from another hook (e.g. useTelemetry)
50|    const cachedKill = localStorage.getItem('TAD_FORCE_KILL_SWITCH');
51|    if (cachedKill === 'true') {
52|      // Check if we're still within the grace period
53|      const cachedExpiry = localStorage.getItem(SUBSCRIPTION_EXPIRY_KEY);
54|      if (cachedExpiry) {
55|        const expiryDate = new Date(cachedExpiry);
56|        const gracePeriodEnd = new Date(expiryDate.getTime() + GRACE_PERIOD_MS);
57|        if (gracePeriodEnd > new Date()) {
58|          // Within grace period — temporarily re-allow telemetry
59|          suspendedRef.current = false;
60|          console.warn('[TAD] Within 48h grace period after subscription expiry. Telemetry continues.');
61|        } else {
62|          // Grace period expired — remain suspended
63|          suspendedRef.current = true;
64|          return;
65|        }
66|      } else {
67|        suspendedRef.current = true;
68|        return; // Don't start tracking if already suspended without expiry info
69|      }
70|    }
71|
72|    const liveChannel = supabase.channel('fleet_tracking_live', {
73|      config: { broadcast: { ack: true } },
74|    });
75|
76|    liveChannel.subscribe((status, error) => {
77|      if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
78|        console.error('[TAD_REALTIME][DRIVER] Broadcast channel rejected or closed', {
79|          status,
80|          error,
81|          channel: 'fleet_tracking_live',
82|        });
83|      }
84|    });
85|
86|    const handleSuspension = (subscriptionEnd?: string) => {
87|      // ── REVENUE SHIELD: Kill-Switch enforcement ──
88|      suspendedRef.current = true;
89|
90|      // Cache subscription expiry for grace period calculation
91|      if (subscriptionEnd) {
92|        localStorage.setItem(SUBSCRIPTION_EXPIRY_KEY, subscriptionEnd);
93|      }
94|
95|      // Cache flag in localStorage for cross-hook propagation
96|      localStorage.setItem('TAD_FORCE_KILL_SWITCH', 'true');
97|      localStorage.setItem(SUBSCRIPTION_CACHE_KEY, 'SUSPENDED');
98|
99|      // Activate PaymentLockOverlay
100|      setLock(true, 'Suscripción vencida. Pago de RD$6,000 requerido.');
101|
102|      // Stop GPS tracking
103|      if (watchIdRef.current !== null) {
104|        navigator.geolocation.clearWatch(watchIdRef.current);
105|        watchIdRef.current = null;
106|      }
107|
108|      // Destroy Supabase Realtime channel
109|      void supabase.removeChannel(liveChannel);
110|    };
111|
112|    const clearSuspension = () => {
113|      suspendedRef.current = false;
114|      localStorage.removeItem('TAD_FORCE_KILL_SWITCH');
115|      localStorage.removeItem(SUBSCRIPTION_EXPIRY_KEY);
116|      localStorage.setItem(SUBSCRIPTION_CACHE_KEY, 'ACTIVE');
117|      setLock(false, '');
118|    };
119|
120|    watchIdRef.current = navigator.geolocation.watchPosition(
121|      (position) => {
122|        // Block all telemetry if suspended
123|        if (suspendedRef.current) return;
124|
125|        const now = Date.now();
126|        const isOnline = (localStorage.getItem('TAD_DRIVER_STATUS') || 'ONLINE').toUpperCase() === 'ONLINE';
127|
128|        if (isOnline && now - lastLivePingTime.current >= 30000) {
129|          lastLivePingTime.current = now;
130|          const ping = {
131|            driverId,
132|            deviceId: localStorage.getItem('TAD_DEVICE_ID') || 'unknown',
133|            lat: position.coords.latitude,
134|            lng: position.coords.longitude,
135|            speed: position.coords.speed || 0,
136|            bearing: position.coords.heading || 0,
137|            timestamp: new Date(position.timestamp).toISOString(),
138|          };
139|
140|          void liveChannel.send({
141|            type: 'broadcast',
142|            event: 'telemetry_ping',
143|            payload: ping,
144|          }).then((status) => {
145|            if (status !== 'ok') {
146|              console.error('[TAD_REALTIME][DRIVER] telemetry_ping was not acknowledged', {
147|                status,
148|                channel: 'fleet_tracking_live',
149|                driverId,
150|              });
151|            }
152|          }).catch((error) => {
153|            console.error('[TAD_REALTIME][DRIVER] telemetry_ping publish failed', error);
154|          });
155|        }
156|
157|        // 1. Acumular punto en el Buffer Local (IndexedDB)
158|        const addPoint = async () => {
159|          const db = await dbPromise;
160|          await db.add(STORE_NAME, {
161|            device_id: localStorage.getItem('TAD_DEVICE_ID') || 'unknown',
162|            driver_id: driverId,
163|            latitude: position.coords.latitude,
164|            longitude: position.coords.longitude,
165|            speed: position.coords.speed || 0,
166|            captured_at: new Date(position.timestamp).toISOString(),
167|          });
168|        };
169|        addPoint().catch(console.error);
170|
171|        // 5-minute debounce for bulk flush (300,000 ms)
172|        if (now - lastSyncTime.current < 300000) return;
173|        
174|        // No sincronizar si no hay red
175|        if (!navigator.onLine) return;
176|        
177|        lastSyncTime.current = now;
178|
179|        const flushBatch = async () => {
180|          const db = await dbPromise;
181|          const allRecords = await db.getAll(STORE_NAME);
182|          if (allRecords.length === 0) return;
183|
184|          try {
185|            const response = await fetch(POSTGREST_RPC_URL, {
186|              method: 'POST',
187|              headers: {
188|                'Content-Type': 'application/json',
189|                'apikey': ANON_KEY!,
190|                'Authorization': `Bearer ${ANON_KEY}`,
191|              },
192|              body: JSON.stringify({ telemetry_payload: allRecords }),
193|            });
194|
195|            if (response.status === 402 || response.status === 403) {
196|              // Manejo de Error 402/403 de RLS/Supabase
197|              response.json().then((body) => {
198|                const subscriptionEnd = body?.subscriptionEnd || body?.subscription_end;
199|                handleSuspension(subscriptionEnd);
200|              }).catch(() => handleSuspension());
201|              return;
202|            }
203|
204|            if (response.ok) {
205|              const tx = db.transaction(STORE_NAME, 'readwrite');
206|              await tx.store.clear();
207|              await tx.done;
208|              clearSuspension();
209|            } else {
210|              console.error('[TELEMETRY_HTTP] Non-OK response:', response.status);
211|            }
212|          } catch (err) {
213|            console.error('Error flushing telemetry batch to PostgREST:', err);
214|          }
215|        };
216|        flushBatch();
217|      },
218|      (error) => {
219|        console.error('Geolocation error:', error);
220|      },
221|      {
222|        enableHighAccuracy: true,
223|        timeout: 10000,
224|        maximumAge: 0,
225|      }
226|    );
227|
228|    return () => {
229|      if (watchIdRef.current !== null) {
230|        navigator.geolocation.clearWatch(watchIdRef.current);
231|      }
232|      void supabase.removeChannel(liveChannel);
233|    };
234|  }, [driverId, setLock]);
235|};", "total_lines": 234, "file_size": 8879, "truncated": false, "is_binary": false, "is_image": false}

{"content": "1|// apps/driver/hooks/useTelemetry.ts
2|/**
3| * useTelemetry — Hook de Telemetría Offline-First con soporte para IndexedDB
4| *
5| * Reglas de negocio:
6| *  - Agrupa coordenadas en lotes de BATCH_SIZE (10) o flushea cada FLUSH_INTERVAL_MS (300s)
7| *  - Almacena el buffer en IndexedDB para mayor resiliencia
8| *  - Al recibir HTTP 402 del backend → destruye el worker GPS y activa el kill-switch
9| *  - Sin dependencias de librerías de UI externas
10| */
11|
12|import { useEffect, useRef, useCallback, useState } from 'react';
13|import { supabase } from '@tad/services';
14|import { usePaymentStore } from '../store/usePaymentStore';
15|import { openDB } from '../utils/indexedDb';
16|
17|// ─── Constantes ──────────────────────────────────────────────────────────────
18|const BATCH_SIZE = 10;
19|const FLUSH_INTERVAL_MS = 300_000; // 5 minutos (debounce estricto V12)
20|const MAX_OFFLINE_RECORDS = 500;
21|
22|export type ConnectionStatus = 'online' | 'offline' | 'syncing';
23|
24|export interface TelemetryCoord {
25|  lat: number;
26|  lng: number;
27|  ts: number;
28|  accuracy?: number;
29|}
30|
31|export interface UseTelemetryReturn {
32|  connectionStatus: ConnectionStatus;
33|  batchCount: number;     // coordenadas actuales en el buffer (0–10)
34|  offlineCount: number;   // registros guardados offline pendientes de sync
35|  syncPending: () => Promise<{ processed: number; remaining: number; success: boolean }>;
36|  startTracking: () => void;
37|  stopTracking: () => void;
38|  isTracking: boolean;
39|}
40|
41|// ─── Helpers IndexedDB ────────────────────────────────────────────────────────
42|async function readCoordsByStatus(status: 'batch' | 'offline'): Promise<TelemetryCoord[]> {
43|  try {
44|    const db = await openDB();
45|    const tx = db.transaction('telemetry', 'readonly');
46|    const store = tx.objectStore('telemetry');
47|    return new Promise((resolve) => {
48|      const request = store.getAll();
49|      request.onsuccess = () => {
50|        const all = request.result || [];
51|        resolve(all.filter((x: any) => x.status === status));
52|      };
53|      request.onerror = () => resolve([]);
54|    });
55|  } catch (err) {
56|    console.error('IndexedDB read error:', err);
57|    return [];
58|  }
59|}
60|
61|async function writeBatchCoords(batch: TelemetryCoord[]): Promise<void> {
62|  try {
63|    const db = await openDB();
64|    const tx = db.transaction('telemetry', 'readwrite');
65|    const store = tx.objectStore('telemetry');
66|    
67|    return new Promise<void>((resolve) => {
68|      const allRequest = store.getAll();
69|      allRequest.onsuccess = () => {
70|        const all = allRequest.result || [];
71|        const batchKeys = all.filter((x: any) => x.status === 'batch').map((x: any) => x.ts);
72|        batchKeys.forEach((key: number) => store.delete(key));
73|        
74|        batch.forEach((coord) => {
75|          store.put({ ...coord, status: 'batch' });
76|        });
77|        resolve();
78|      };
79|      allRequest.onerror = () => resolve();
80|    });
81|  } catch (err) {
82|    console.error('IndexedDB writeBatch error:', err);
83|  }
84|}
85|
86|async function appendOfflineCoords(coords: TelemetryCoord[]): Promise<void> {
87|  try {
88|    const db = await openDB();
89|    const tx = db.transaction('telemetry', 'readwrite');
90|    const store = tx.objectStore('telemetry');
91|    
92|    return new Promise<void>((resolve) => {
93|      const allRequest = store.getAll();
94|      allRequest.onsuccess = () => {
95|        const all = allRequest.result || [];
96|        const offlineRecords = all.filter((x: any) => x.status === 'offline');
97|        
98|        const merged = [...offlineRecords, ...coords];
99|        const toKeep = merged.slice(-MAX_OFFLINE_RECORDS);
100|        
101|        const toKeepKeys = new Set(toKeep.map((x) => x.ts));
102|        offlineRecords.forEach((x: any) => {
103|          if (!toKeepKeys.has(x.ts)) {
104|            store.delete(x.ts);
105|          }
106|        });
107|        
108|        toKeep.forEach((coord) => {
109|          store.put({ ...coord, status: 'offline' });
110|        });
111|        resolve();
112|      };
113|      allRequest.onerror = () => resolve();
114|    });
115|  } catch (err) {
116|    console.error('IndexedDB appendOffline error:', err);
117|  }
118|}
119|
120|async function clearOfflineCoords(): Promise<void> {
121|  try {
122|    const db = await openDB();
123|    const tx = db.transaction('telemetry', 'readwrite');
124|    const store = tx.objectStore('telemetry');
125|    return new Promise<void>((resolve) => {
126|      const allRequest = store.getAll();
127|      allRequest.onsuccess = () => {
128|        const all = allRequest.result || [];
129|        const offlineKeys = all.filter((x: any) => x.status === 'offline').map((x: any) => x.ts);
130|        offlineKeys.forEach((key: number) => store.delete(key));
131|        resolve();
132|      };
133|      allRequest.onerror = () => resolve();
134|    });
135|  } catch (err) {
136|    console.error('IndexedDB clearOffline error:', err);
137|  }
138|}
139|
140|async function writeOfflineCoords(coords: TelemetryCoord[]): Promise<void> {
141|  try {
142|    const db = await openDB();
143|    const tx = db.transaction('telemetry', 'readwrite');
144|    const store = tx.objectStore('telemetry');
145|    return new Promise<void>((resolve) => {
146|      const allRequest = store.getAll();
147|      allRequest.onsuccess = () => {
148|        const all = allRequest.result || [];
149|        const offlineKeys = all.filter((x: any) => x.status === 'offline').map((x: any) => x.ts);
150|        offlineKeys.forEach((key: number) => store.delete(key));
151|
152|        coords.slice(-MAX_OFFLINE_RECORDS).forEach((coord) => {
153|          store.put({ ...coord, status: 'offline' });
154|        });
155|        resolve();
156|      };
