572|      void supabase.removeChannel(liveChannelRef.current);
573|      liveChannelRef.current = null;
574|    }
575|
576|    setIsTracking(false);
577|  }, []);
578|
579|  // ─── Listeners de red ─────────────────────────────────────────────────────
580|  useEffect(() => {
581|    const handleOnline = () => {
582|      isOnlineRef.current = true;
583|      readCoordsByStatus('offline').then((offlineQueue) => {
584|        if (offlineQueue.length > 0) {
585|          void syncPending();
586|          return;
587|        }
588|        setConnectionStatus('online');
589|        void flushBatch(true);
590|      });
591|    };
592|    const handleOffline = () => {
593|      isOnlineRef.current = false;
594|      setConnectionStatus('offline');
595|    };
596|
597|    window.addEventListener('online', handleOnline);
598|    window.addEventListener('offline', handleOffline);
599|
600|    // Escuchar mensaje del Service Worker para flush
601|    const handleSWMessage = (evt: MessageEvent) => {
602|      if (evt.data?.type === 'FLUSH_TELEMETRY') {
603|        flushBatch(true);
604|      }
605|    };
606|    navigator.serviceWorker?.addEventListener('message', handleSWMessage);
607|
608|    return () => {
609|      window.removeEventListener('online', handleOnline);
610|      window.removeEventListener('offline', handleOffline);
611|      navigator.serviceWorker?.removeEventListener('message', handleSWMessage);
612|    };
613|  }, [flushBatch, syncPending]);
614|
615|  // ─── Cleanup al desmontar ─────────────────────────────────────────────────
616|  useEffect(() => {
617|    return () => {
618|      stopTracking();
619|    };
620|  }, [stopTracking]);
621|
622|  return {
623|    connectionStatus,
624|    batchCount,
625|    offlineCount,
626|    syncPending,
627|    startTracking,
628|    stopTracking,
629|    isTracking,
630|  };
631|}
