{"content": "1|// apps/driver/components/BankForm.tsx
2|import React, { useEffect, useState } from 'react';
3|import api from '@tad/services';
4|import { enqueueOfflineAction, syncOfflineQueue } from '../lib/offlineQueue';
5|import {
6|  ChevronRight,
7|  ChevronLeft,
8|  WifiOff,
9|  CheckCircle2,
10|} from 'lucide-react';
11|
12|// ─── Types ────────────────────────────────────────────────────────────────────
13|
14|type BankAccountType = 'AHORRO' | 'CORRIENTE';
15|
16|interface BankFormData {
17|  banco: string;
18|  cuenta: string;
19|  tipo: BankAccountType;
20|  ownerName: string;
21|  cedula: string;
22|}
23|
24|interface BankFormProps {
25|  driverId: string;
26|  onSuccess: () => void;
27|}
28|
29|// ─── Constants ────────────────────────────────────────────────────────────────
30|
31|const BANK_OPTIONS: { value: string; label: string; short: string }[] = [
32|  { value: 'BPD',        label: 'Banco Popular Dominicano', short: 'BPD'  },
33|  { value: 'BHD',        label: 'BHD León',                 short: 'BHD'  },
34|  { value: 'BR',         label: 'Banreservas',              short: 'BR'   },
35|  { value: 'SCOTIABANK', label: 'Scotiabank DR',            short: 'SCO'  },
36|  { value: 'APAP',       label: 'Asociación Popular',       short: 'APAP' },
37|];
38|
39|const STEPS = ['Banco', 'Cuenta', 'Tipo', 'Titular', 'Cédula'] as const;
40|
41|// ─── Helpers ──────────────────────────────────────────────────────────────────
42|
43|const normalizeAccountType = (value: unknown): BankAccountType => {
44|  if (value === 'CHECKING' || value === 'CORRIENTE') return 'CORRIENTE';
45|  return 'AHORRO';
46|};
47|
48|const buildBankPayload = (data: BankFormData) => ({
49|  banco:     data.banco,
50|  cuenta:    data.cuenta,
51|  tipo:      normalizeAccountType(data.tipo),
52|  cedula:    data.cedula,
53|  ownerName: data.ownerName.trim(),
54|});
55|
56|export const getDriverBankPendingKey = (driverId: string) =>
57|  `tad_driver_bank_pending_${driverId}`;
58|
59|// ─── Component ────────────────────────────────────────────────────────────────
60|
61|export const BankForm: React.FC<BankFormProps> = ({ driverId, onSuccess }) => {
62|  const [step, setStep]       = useState(1);
63|  const [submitting, setSubmitting] = useState(false);
64|  const [savedOffline, setSavedOffline] = useState(false);
65|  const [isOffline, setIsOffline] = useState(false);
66|  const [formData, setFormData] = useState<BankFormData>({
67|    banco:     '',
68|    cuenta:    '',
69|    tipo:      'AHORRO',
70|    ownerName: '',
71|    cedula:    '',
72|  });
73|
74|  const draftKey  = `tad_driver_bank_draft_${driverId}`;
75|  const pendingKey = getDriverBankPendingKey(driverId);
76|
77|  // ── Hydrate draft + online listeners ────────────────────────────────────────
78|  useEffect(() => {
79|    if (typeof window === 'undefined') return;
80|
81|    setIsOffline(!navigator.onLine);
82|
83|    try {
84|      const raw = localStorage.getItem(draftKey);
85|      if (raw) {
86|        const parsed = JSON.parse(raw);
87|        setFormData({
88|          banco:     typeof parsed?.banco     === 'string' ? parsed.banco     : '',
89|          cuenta:    typeof parsed?.cuenta    === 'string' ? parsed.cuenta    : '',
90|          tipo:      normalizeAccountType(parsed?.tipo),
91|          ownerName: typeof parsed?.ownerName === 'string' ? parsed.ownerName : '',
92|          cedula:    typeof parsed?.cedula    === 'string' ? parsed.cedula    : '',
93|        });
94|      }
95|    } catch {
96|      // Borrador corrupto — ignorar
97|    }
98|
99|    const handleOnline  = () => { setIsOffline(false); void syncOfflineQueue(); };
100|    const handleOffline = () => setIsOffline(true);
101|
102|    window.addEventListener('online',  handleOnline);
103|    window.addEventListener('offline', handleOffline);
104|    return () => {
105|      window.removeEventListener('online',  handleOnline);
106|      window.removeEventListener('offline', handleOffline);
107|    };
108|  }, [draftKey]);
109|
110|  // ── Field updater (auto-saves draft) ────────────────────────────────────────
111|  const handleChange = (field: keyof BankFormData, value: string) => {
112|    setFormData(prev => {
113|      const next = {
114|        ...prev,
115|        [field]: field === 'tipo' ? normalizeAccountType(value) : value,
116|      } as BankFormData;
117|      if (typeof window !== 'undefined') {
118|        localStorage.setItem(draftKey, JSON.stringify(next));
119|      }
120|      return next;
121|    });
122|  };
123|
124|  // ── Offline queue ────────────────────────────────────────────────────────────
125|  const queueOfflineSave = async (data: BankFormData) => {
126|    if (typeof window !== 'undefined') {
127|      localStorage.setItem(draftKey,   JSON.stringify(data));
128|      localStorage.setItem(pendingKey, '1');
129|    }
130|    await enqueueOfflineAction('/wallet/bank', buildBankPayload(data), 'PUT');
131|  };
132|
133|  // ── Online submit ────────────────────────────────────────────────────────────
134|  const submitData = async (data: BankFormData) => {
135|    try {
136|      await api.put('/wallet/bank', buildBankPayload(data), {
137|        headers: { 'Idempotency-Key': crypto.randomUUID() },
138|      });
139|      if (typeof window !== 'undefined') {
140|        localStorage.removeItem(draftKey);
141|        localStorage.removeItem(pendingKey);
142|      }
143|      onSuccess();
144|    } catch (error: any) {
145|      const status       = error?.response?.status;
146|      const errorMessage =
147|        error?.response?.data?.message ||
148|        error?.message ||
149|        'No se pudo guardar la información bancaria.';
150|      const isNetworkFailure =
151|        !navigator.onLine ||
152|        !error?.response ||
153|        /failed to fetch|network|load failed/i.test(String(errorMessage).toLowerCase());
154|
155|      if (isNetworkFailure || (typeof status === 'number' && status >= 500)) {
156|        await queueOfflineSave(data);
157|        setSavedOffline(true);
158|        setTimeout(() => onSuccess(), 1800);
159|        return;
160|      }
161|      throw new Error(errorMessage);
162|    }
163|  };
164|
165|  // ── Step navigation ──────────────────────────────────────────────────────────
166|  const handleNext = async () => {
167|    if (step === 2 && !/^\d{10,20}$/.test(formData.cuenta)) {
168|      alert('Número de cuenta inválido (10–20 dígitos numéricos)');
169|      return;
170|    }
171|    if (step === 5 && !/^\d{11}$/.test(formData.cedula)) {
172|      alert('Cédula inválida (11 dígitos, sin guiones)');
173|      return;
174|    }
175|    if (step < 5) {
176|      setStep(prev => prev + 1);
177|      return;
178|    }
179|
180|    // Último paso → enviar
181|    if (isOffline || !navigator.onLine) {
182|      await queueOfflineSave(formData);
183|      setSavedOffline(true);
184|      setTimeout(() => onSuccess(), 1800);
185|      return;
186|    }
187|
188|    setSubmitting(true);
189|    try {
190|      await submitData(formData);
191|    } catch (err) {
192|      const msg = err instanceof Error ? err.message : 'No se pudo guardar la información bancaria.';
193|      alert(msg);
194|    } finally {
195|      setSubmitting(false);
196|    }
197|  };
198|
199|  // ─── Confirmación offline ────────────────────────────────────────────────────
200|  if (savedOffline) {
201|    return (
202|      <div className="flex flex-col items-center justify-center gap-5 py-8 text-center">
203|        <div className="relative">
204|          <div className="absolute inset-0 rounded-full bg-emerald-500/20 blur-[20px]" />
205|          <div className="relative h-16 w-16 rounded-full border border-emerald-500/20 bg-emerald-500/10 flex items-center justify-center">
206|            <CheckCircle2 className="h-8 w-8 text-emerald-400" />
207|          </div>
208|        </div>
209|        <div>
210|          <p className="text-[10px] font-black uppercase tracking-[0.25em] text-emerald-400">
211|            Guardado sin conexión
212|          </p>
213|          <p className="mt-2 text-sm leading-relaxed text-zinc-400 max-w-xs">
214|            Tu información bancaria quedó cifrada en el dispositivo y se sincronizará
