{"content":"// apps/driver/components/dashboard/BottomNavigationBar.tsx
/**
 * BottomNavigationBar — Barra de navegación inferior premium
 *
 * Mobile-first, 4 tabs (Inicio, Rutas, Billetera, Ajustes).
 * Glassmorphism, animaciones framer-motion, safe-area-inset.
 * z-30 para que modales (DriverOnboardingModal z-[95], LockdownScreen z-[100])
 * queden por encima.
 *
 * @usage
 *   <BottomNavigationBar activeTab="home" onChange={(tab) => setActiveTab(tab)} />
 */
'use client';

import React from 'react';
import { Home, MapPin, Wallet, Settings } from 'lucide-react';
import { motion } from 'framer-motion';

export type DriverTab = 'home' | 'routes' | 'wallet' | 'settings';

interface NavItem {
  id: DriverTab;
  label: string;
  icon: React.ComponentType<{ size?: number; className?: string }>;
}

const NAV_ITEMS: NavItem[] = [
  { id: 'home',     label: 'Inicio',     icon: Home },
  { id: 'routes',   label: 'Rutas',      icon: MapPin },
  { id: 'wallet',   label: 'Billetera',  icon: Wallet },
  { id: 'settings', label: 'Ajustes',    icon: Settings },
];

interface BottomNavigationBarProps {
  activeTab: DriverTab;
  onChange: (tab: DriverTab) => void;
}

export const BottomNavigationBar: React.FC<BottomNavigationBarProps> = ({
  activeTab,
  onChange,
}) => {
  return (
    <nav
      className="fixed bottom-0 left-0 right-0 z-30 pb-[env(safe-area-inset-bottom,0px)] bg-black/80 backdrop-blur-3xl border-t border-white/[0.06] shadow-[0_-10px_40px_rgba(0,0,0,0.6)]"
      role="navigation"
      aria-label="Navegación principal del conductor"
    >
      <div className="mx-auto flex h-16 max-w-lg items-center justify-around px-2">
        {NAV_ITEMS.map((item) => {
          const isActive = activeTab === item.id;
          const Icon = item.icon;

          return (
            <motion.button
              key={item.id}
              onClick={() => onChange(item.id)}
              whileTap={{ scale: 0.9 }}
              className={`relative flex flex-col items-center justify-center gap-0.5 w-20 h-14 rounded-2xl transition-colors duration-200 ${
                isActive
                  ? 'text-[#FFD400]'
                  : 'text-zinc-600 active:text-zinc-400'
              }`}
              aria-current={isActive ? 'page' : undefined}
              aria-label={item.label}
            >
              {/* Highlight background for active tab */}
              {isActive && (
                <motion.div
                  layoutId="bottom-nav-active-bg"
                  className="absolute inset-0 rounded-2xl bg-[#FFD400]/5 border border-[#FFD400]/10"
                  transition={{ type: 'spring', stiffness: 500, damping: 30 }}
                />
              )}

              {/* Icon container */}
              <div className="relative z-10 flex items-center justify-center">
                <Icon size={22} />
              </div>

              {/* Label */}
              <span
                className={`relative z-10 text-[9px] font-black uppercase tracking-[0.15em] transition-colors duration-200 ${
                  isActive ? 'text-[#FFD400]' : 'text-zinc-600'
                }`}
              >
                {item.label}
              </span>

              {/* Active dot indicator */}
              {isActive && (
                <motion.div
                  layoutId="bottom-nav-active-dot"
                  className="absolute -top-0.5 w-5 h-0.5 rounded-full bg-[#FFD400] shadow-[0_0_10px_rgba(255,212,0,0.6)]"
                  transition={{ type: 'spring', stiffness: 500, damping: 30 }}
                />
              )}
            </motion.button>
          );
        })}
      </div>
    </nav>
  );
};

export default BottomNavigationBar;","path":"apps/driver/components/dashboard/BottomNavigationBar.tsx"}

{"content":"// apps/driver/components/dashboard/RoutesTab.tsx
/**
 * RoutesTab — Vista de Rutas / Mapa de Telemetría
 *
 * Muestra estadísticas en vivo del GPS del conductor:
 * - Velocidad actual y bearing
 * - Estado del batch de telemetría
 * - Efecto visual de mapa con glow pulsante
 * - Acción rápida para compartir ubicación
 *
 * Totalmente estática (no requiere Leaflet ni librerías externas pesadas).
 * Los datos en vivo vienen del shell (useTelemetry).
 */
'use client';

import React from 'react';
import { motion } from 'framer-motion';
import {
  Navigation,
  Signal,
  MapPin,
  Activity,
  RefreshCw,
} from 'lucide-react';

interface RoutesTabProps {
  connectionStatus: 'online' | 'offline' | 'syncing';
  batchCount: number;
  offlineCount: number;
  isTracking: boolean;
  onSync: () => void;
  syncingNow: boolean;
}

export const RoutesTab: React.FC<RoutesTabProps> = ({
  connectionStatus,
  batchCount,
  offlineCount,
  isTracking,
  onSync,
  syncingNow,
}) => {
  const isOffline = connectionStatus === 'offline';
  const isSyncing = connectionStatus === 'syncing';

  return (
    <section aria-labelledby="routes-tab-title" className="space-y-5">
      {/* Title */}
      <div>
        <h2
          id="routes-tab-title"
          className="text-xs font-black uppercase tracking-[0.25em] text-zinc-500"
        >
          Monitoreo de ruta
        </h2>
        <p className="mt-1 text-base font-bold text-zinc-300">
          Telemetría GPS en vivo
        </p>
      </div>

      {/* Map Preview Card — decorativo, estilo shine glass */}
      <div className="relative h-48 overflow-hidden rounded-[2.5rem] border border-white/[0.04] bg-gradient-to-br from-zinc-900 via-zinc-950 to-black">
        {/* Grid overlay */}
        <div
          className="absolute inset-0 opacity-[0.03]"
          style={{
            backgroundImage:
              'linear-gradient(rgba(255,212,0,0.3) 1px, transparent 1px), linear-gradient(90deg, rgba(255,212,0,0.3) 1px, transparent 1px)',
            backgroundSize: '40px 40px',
          }}
        />

        {/* Scan line animation */}
        <div className="absolute left-0 right-0 h-0.5 bg-gradient-to-r from-transparent via-[#FFD400]/20 to-transparent animate-map-scan" />

        {/* Center pin */}
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="relative">
            <div className="absolute inset-0 rounded-full bg-[#FFD400]/10 blur-[30px] animate-pulse-soft" />
            <div className="relative flex h-14 w-14 items-center justify-center rounded-2xl border border-[#FFD400]/20 bg-black/60 backdrop-blur-xl shadow-[0_0_40px_rgba(255,212,0,0.15)]">
              <MapPin className="h-6 w-6 text-[#FFD400]" />
            </div>
          </div>
        </div>

        {/* Bottom status strip */}
        <div className="absolute bottom-4 left-4 right-4 flex items-center justify-between rounded-xl border border-white/[0.04] bg-black/40 px-3.5 py-2 backdrop-blur-md">
          <div className="flex items-center gap-2.5">
            <div
              className={`h-2 w-2 rounded-full ${
                isOffline
                  ? 'bg-red-500'
                  : isSyncing
                    ? 'bg-[#FFD400] animate-pulse-soft'
                    : 'bg-emerald-500'
              }`}
            />
            <span className="text-[10px] font-black uppercase tracking-[0.15em] text-zinc-400">
              {isOffline
                ? 'Sin conexión'
                : isSyncing
                  ? 'Sincronizando...'
                  : isTracking
                    ? 'Rastreo activo'
                    : 'GPS detenido'}
            </span>
          </div>
          <span className="text-[10px] font-mono text-zinc-600">
            BATCH {batchCount}/10
          </span>
        </div>
      </div>

      {/* GPS Stats Grid */}
      <div className="grid grid-cols-3 gap-3">
        {[
          {
            label: 'Tracking',
            value: isTracking ? 'ACTIVO' : 'INACTIVO',
            color: isTracking ? 'text-emerald-400' : 'text-zinc-600',
            icon: Activity,
          },
          {
            label: 'Batch GPS',
            value: `${batchCount}/10`,
            color: 'text-[#FFD400]',
            icon: Signal,
          },
          {
            label: 'Offline',
            value: `${offlineCount} pts`,
            color: offlineCount > 0 ? 'text-amber-400' : 'text-emerald-400',
            icon: Navigation,
          },
        ].map((stat, i) => {
          const Icon = stat.icon;
          return (
            <div
              key={i}
              className="flex flex-col items-center gap-2 rounded-2xl border border-white/[0.03] bg-white/[0.02] px-3 py-4 text-center"
            >
              <Icon className={`h-4 w-4 ${stat.color}`} />
              <p className="text-[10px] font-black uppercase tracking-[0.15em] text-zinc-600">
                {stat.label}
              </p>
              <p className={`text-xs font-black ${stat.color}`}>
                {stat.value}
              </p>
            </div>
          );
        })}
      </div>

      {/* Sync Button */}
      <motion.button
        whileTap={{ scale: 0.95 }}
        onClick={onSync}
        disabled={offlineCount === 0 || syncingNow}
        className="flex w-full items-center justify-center gap-3 rounded-2xl border border-white/[0.06] bg-white/[0.03] px-5 py-4 text-sm font-black uppercase tracking-[0.15em] text-zinc-300 transition hover:bg-white/[0.06] hover:text-white disabled:cursor-not-allowed disabled:opacity-40"
      >
        <RefreshCw
          className={`h-4 w-4 ${syncingNow ? 'animate-spin' : ''}`}
        />
        <span>
          {syncingNow
            ? 'Sincronizando...'
            : offlineCount > 0
              ? `Sincronizar ${offlineCount} puntos pendientes`
              : 'Todo sincronizado ✓'}
        </span>
      </motion.button>
    </section>
  );
};

export default RoutesTab;","path":"apps/driver/components/dashboard/RoutesTab.tsx"}

{"content":"// apps/driver/components/dashboard/SettingsTab.tsx
/**
 * SettingsTab — Vista de Ajustes y Soporte
 *
 * Acciones tácticas del conductor:
 * - Soporte WhatsApp, Reportar falla
 * - Sincronización forzada
 * - Referir conductores
 * - Cerrar sesión
 * - Información de versión y debug
 *
 * Reemplaza los ActionButton del dashboard original con un layout
 * tipo "settings list" optimizado para móvil (hitboxes grandes, 48px+).
 */
'use client';

import React from 'react';
import { motion } from 'framer-motion';
import {
  MessageCircle,
  AlertTriangle,
  RefreshCw,
  UserPlus,
  LogOut,
  Info,
  Smartphone,
  Wifi,
} from 'lucide-react';

interface SettingsTabProps {
  connectionStatus: 'online' | 'offline' | 'syncing';
  batchCount: number;
  offlineCount: number;
  isTracking: boolean;
  onSync: () => void;
  onSupport: () => void;
  onReportFalla: () => void;
  onReferir: () => void;
  onLogout: () => void;
  syncingNow: boolean;
}

interface SettingsItemProps {
  icon: React.ReactNode;
  label: string;
  sublabel?: string;
  onClick: () => void;
  disabled?: boolean;
  color?: string;
}

function SettingsItem({
  icon,
  label,
  sublabel,
  onClick,
  disabled = false,
  color = 'text-zinc-400',
}: SettingsItemProps) {
  return (
    <motion.button
      whileTap={{ scale: 0.97 }}
      onClick={onClick}
      disabled={disabled}
      className="flex w-full items-center gap-4 rounded-2xl border border-white/[0.04] bg-white/[0.02] px-5 py-4 text-left transition hover:border-white/[0.08] hover:bg-white/[0.04] disabled:cursor-not-allowed disabled:opacity-40 active:bg-white/[0.06]"
    >
      <div
        className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/[0.04] bg-white/[0.03] ${color}`}
      >
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-black text-white">{label}</p>
        {sublabel && (
          <p className="mt-0.5 truncate text-[10px] font-bold uppercase tracking-[0.1em] text-zinc-600">
            {sublabel}
          </p>
        )}
      </div>
      <svg
        className="h-4 w-4 shrink-0 text-zinc-700"
        fill="none"
        viewBox="0 0 24 24"
        stroke="currentColor"
        strokeWidth={2}
      >
        <path
          strokeLinecap="round"
          strokeLinejoin="round"
          d="M9 5l7 7-7 7"
        />
      </svg>
    </motion.button>
  );
}

export const SettingsTab: React.FC<SettingsTabProps> = ({
  connectionStatus,
  batchCount,
  offlineCount,
  isTracking,
  onSync,
  onSupport,
  onReportFalla,
  onReferir,
  onLogout,
  syncingNow,
}) => {
  const isOffline = connectionStatus === 'offline';

  return (
    <section aria-labelledby="settings-tab-title" className="space-y-5">
      {/* Title */}
      <div>
        <h2
          id="settings-tab-title"
          className="text-xs font-black uppercase tracking-[0.25em] text-zinc-500"
        >
          Ajustes
        </h2>
        <p className="mt-1 text-base font-bold text-zinc-300">
          Soporte y configuración
        </p>
      </div>

      {/* Connectivity Status Card */}
      <div className="rounded-[2rem] border border-white/[0.04] bg-white/[0.02] p-4">
        <div className="flex items-center gap-3">
          <div
            className={`flex h-10 w-10 items-center justify-center rounded-xl border ${
              isOffline
                ? 'border-red-500/20 bg-red-500/5 text-red-400'
                : 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400'
            }`}
          >
            <Wifi className="h-5 w-5" />
          </div>
          <div className="flex-1">
            <p className="text-sm font-black text-white">
              {isOffline ? 'Sin conexión' : 'Conectado'}
            </p>
            <p className="text-[10px] font-bold uppercase tracking-[0.1em] text-zinc-600">
              {isTracking ? 'GPS activo' : 'GPS detenido'} · Batch {batchCount}
              /10 · {offlineCount > 0 ? `${offlineCount} pts offline` : '0 pts pendientes'}
            </p>
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="space-y-2">
        <SettingsItem
          icon={<MessageCircle className="h-5 w-5" />}
          label="Soporte por WhatsApp"
          sublabel="Respuesta rápida en minutos"
          onClick={onSupport}
          color="text-emerald-400"
        />

        <SettingsItem
          icon={<AlertTriangle className="h-5 w-5" />}
          label="Reportar falla"
          sublabel="Dispositivo, app o telemetría"
          onClick={onReportFalla}
          color="text-red-400"
        />

        <SettingsItem
          icon={
            <RefreshCw
              className={`h-5 w-5 ${syncingNow ? 'animate-spin' : ''}`}
            />
          }
          label="Sincronizar datos"
          sublabel={
            offlineCount > 0
              ? `${offlineCount} puntos offline pendientes`
              : 'Todo al día'
          }
          onClick={onSync}
          disabled={offlineCount === 0 || syncingNow}
          color="text-[#FFD400]"
        />

        <SettingsItem
          icon={<UserPlus className="h-5 w-5" />}
          label="Referir conductor"
          sublabel="Gana bonos por cada referido activo"
          onClick={onReferir}
          color="text-blue-400"
        />

        <SettingsItem
          icon={<LogOut className="h-5 w-5" />}
          label="Cerrar sesión"
          sublabel="Desconectar de la plataforma"
          onClick={onLogout}
          color="text-zinc-400"
        />
      </div>

      {/* Version Info */}
      <div className="flex items-center gap-3 rounded-2xl border border-white/[0.02] bg-white/[0.01] px-4 py-3">
        <Info className="h-4 w-4 shrink-0 text-zinc-700" />
        <div className="flex-1">
          <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-zinc-700">
            TAD Driver Portal v12.0.0
          </p>
          <p className="mt-0.5 text-[9px] font-mono text-zinc-800">
            GPS: {isTracking ? 'ACTIVO' : 'INACTIVO'} · Red:{' '}
            {connectionStatus.toUpperCase()} · Build:{' '}
            {process.env.NEXT_PUBLIC_BUILD_HASH || 'dev'}
          </p>
        </div>
        <Smartphone className="h-4 w-4 shrink-0 text-zinc-800" />
      </div>

      {/* Debug trigger (dev only) */}
      {process.env.NODE_ENV !== 'production' && (
        <p className="pt-2 text-center text-[9px] font-bold uppercase tracking-[0.2em] text-zinc-800">
          Debug: usa el botón en la vista Inicio para forzar bloqueo 402
        </p>
      )}
    </section>
  );
};

export default SettingsTab;","path":"apps/driver/components/dashboard/SettingsTab.tsx"}

