/**
 * WalletTab — Vista de Billetera V12 (migrada de /driver/wallet)
 *
 * Contenido reutilizable: balance, racha, meta de retiro, stats rápidas,
 * transacciones recientes.
 *
 * Usa los datos del hub (useDriverHub) que ya están disponibles en el shell.
 * No monta su propio useTelemetry ni useDriverHub.
 */
'use client';

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  ArrowDownLeft,
  ArrowUpRight,
  Clock,
  Flame,
  Target,
  TrendingUp,
} from 'lucide-react';
import clsx from 'clsx';
import api from '@tad/services';
import type { DriverHubData } from '../../hooks/useDriverHub';
import type { WalletState } from './DriverWalletCard';

interface WalletTabProps {
  hubData: DriverHubData | null;
  connectionStatus: 'online' | 'offline' | 'syncing';
  walletState: WalletState | null;
  isLocalMode: boolean;
}

export const WalletTab: React.FC<WalletTabProps> = ({
  hubData,
  connectionStatus,
  walletState,
  isLocalMode,
}) => {
  const [transactions, setTransactions] = useState<any[]>([]);
  const [txLoading, setTxLoading] = useState(true);

  useEffect(() => {
    const loadTransactions = async () => {
      try {
        const txRes = await api
          .get('/drivers/me/transactions')
          .catch(() => ({ data: [] }));
        setTransactions(
          txRes.data?.length
            ? txRes.data
            : [
                {
                  id: 1,
                  type: 'EARNING',
                  amount: 1200,
                  date: 'Hoy, 2:30 PM',
                  desc: 'Bono Diario de Pauta',
                },
                {
                  id: 2,
                  type: 'WITHDRAWAL',
                  amount: -5000,
                  date: 'Ayer, 10:15 AM',
                  desc: 'Transferencia Bancaria',
                },
                {
                  id: 3,
                  type: 'EARNING',
                  amount: 300,
                  date: 'Lun 8, 4:00 PM',
                  desc: 'Bono por Referido',
                },
              ],
        );
      } catch {
        setTransactions([]);
      } finally {
        setTxLoading(false);
      }
    };
    loadTransactions();
  }, []);

  const balance = hubData?.balance ?? walletState?.total ?? 0;
  const nextWithdrawal = 5000;
  const withdrawalProgress = Math.min(100, (balance / nextWithdrawal) * 100);
  const streak = (hubData as any)?.activeDaysStreak || 0;

  return (
    <section
      aria-labelledby="wallet-tab-title"
      className="space-y-5"
    >
      {/* Title */}
      <div>
        <h2
          id="wallet-tab-title"
          className="text-xs font-black uppercase tracking-[0.25em] text-zinc-500"
        >
          Finanzas
        </h2>
        <p className="mt-1 text-base font-bold text-zinc-300">
          Mi Billetera
        </p>
      </div>

      {/* Offline banner */}
      {isLocalMode && (
        <div className="rounded-2xl border border-amber-300/40 bg-amber-500/10 px-4 py-3">
          <p className="text-xs font-black tracking-wide text-amber-200">
            ⚠️ Mostrando datos en caché (modo local)
          </p>
        </div>
      )}

      {/* Balance Card */}
      <div className="relative rounded-[2.5rem] border border-[#FFD400]/15 bg-gradient-to-br from-[#FFD400]/[0.06] to-zinc-950 p-6 overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-[#FFD400]/15 blur-[50px] rounded-full pointer-events-none" />
        <p className="relative text-[10px] font-black uppercase tracking-[0.2em] text-[#FFD400] mb-2">
          Balance Disponible
        </p>
        <h2 className="relative text-4xl font-black tracking-tighter text-white mb-4">
          RD${balance.toLocaleString()}
        </h2>

        {/* Streak Badge */}
        {streak > 0 && (
          <div className="relative flex items-center gap-2 mb-5 px-4 py-2 bg-orange-500/10 border border-orange-500/20 rounded-xl w-fit">
            <Flame className="w-4 h-4 text-orange-400" />
            <span className="text-[10px] font-black text-orange-300 uppercase tracking-widest">
              {streak} días consecutivos
            </span>
          </div>
        )}

        {/* Withdrawal Progress */}
        <div className="relative mb-5 space-y-2">
          <div className="flex justify-between text-[9px] font-black uppercase tracking-widest">
            <span className="text-zinc-500">Meta para retiro</span>
            <span className="text-[#FFD400]">
              RD${nextWithdrawal.toLocaleString()}
            </span>
          </div>
          <div className="w-full h-2 bg-black/40 rounded-full overflow-hidden">
            <motion.div
              initial={{ width: 0 }}
              animate={{ width: `${withdrawalProgress}%` }}
              transition={{ duration: 1, ease: 'easeOut' }}
              className={clsx(
                'h-full rounded-full',
                withdrawalProgress >= 100
                  ? 'bg-emerald-500'
                  : 'bg-[#FFD400]',
              )}
            />
          </div>
          {withdrawalProgress >= 100 && (
            <p className="text-[9px] font-black text-emerald-400 uppercase tracking-widest animate-pulse">
              ¡Meta alcanzada! Puedes retirar
            </p>
          )}
        </div>

        {/* Withdraw Button */}
        <button
          disabled={withdrawalProgress < 100}
          className={clsx(
            'relative flex-1 py-4 px-5 rounded-2xl font-black uppercase tracking-widest text-[10px] flex items-center justify-center gap-2 transition-all w-full',
            withdrawalProgress >= 100
              ? 'bg-[#FFD400] text-black shadow-[0_10px_30px_rgba(255,212,0,0.2)] hover:scale-[1.02] active:scale-95'
              : 'bg-zinc-800 text-zinc-600 cursor-not-allowed',
          )}
        >
          <ArrowUpRight className="w-4 h-4" />
          Retirar
        </button>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-3 gap-3">
        {[
          {
            label: 'Este Mes',
            value: `RD$${(hubData?.projectedEarnings || 0).toLocaleString()}`,
            icon: TrendingUp,
            color: 'text-emerald-400',
          },
          {
            label: 'Referidos',
            value: `RD$${(walletState?.referredDrivers && walletState.referredAdvertisers * 500 || walletState?.referredAdvertisers * 500 || 0).toLocaleString()}`,
            icon: Target,
            color: 'text-blue-400',
          },
          {
            label: 'Bonos',
            value: `RD$${(walletState?.total || 0).toLocaleString()}`,
            icon: Flame,
            color: 'text-orange-400',
          },
        ].map((stat, i) => {
          const Icon = stat.icon;
          return (
            <div
              key={i}
              className="p-4 rounded-2xl bg-white/[0.02] border border-white/5 text-center"
            >
              <Icon className={clsx('w-4 h-4 mx-auto mb-2', stat.color)} />
              <p className="text-[8px] font-black text-zinc-600 uppercase tracking-widest mb-1">
                {stat.label}
              </p>
              <p className="text-xs font-black text-white">{stat.value}</p>
            </div>
          );
        })}
      </div>

      {/* Transactions */}
      <div className="space-y-4">
        <h3 className="text-xs font-black text-zinc-500 uppercase tracking-[0.2em]">
          Actividad Reciente
        </h3>

        {txLoading ? (
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="p-4 rounded-2xl bg-white/[0.02] border border-white/5 flex items-center gap-4 animate-pulse"
              >
                <div className="w-12 h-12 rounded-xl bg-white/5" />
                <div className="flex-1 space-y-2">
                  <div className="h-3 w-32 bg-white/5 rounded" />
                  <div className="h-2 w-20 bg-white/5 rounded" />
                </div>
                <div className="h-4 w-16 bg-white/5 rounded" />
              </div>
            ))}
          </div>
        ) : transactions.length === 0 ? (
          <div className="rounded-2xl border border-white/5 bg-white/[0.02] p-6 text-center">
            <p className="text-sm font-bold text-zinc-500">
              No hay transacciones recientes
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {transactions.map((tx: any) => (
              <motion.div
                key={tx.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: tx.id * 0.1 }}
                className="p-4 rounded-2xl bg-white/[0.02] border border-white/5 flex items-center gap-4"
              >
                <div
                  className={clsx(
                    'w-12 h-12 rounded-xl flex items-center justify-center',
                    tx.type === 'EARNING'
                      ? 'bg-emerald-500/10 text-emerald-500'
                      : 'bg-rose-500/10 text-rose-500',
                  )}
                >
                  {tx.type === 'EARNING' ? (
                    <ArrowDownLeft className="w-5 h-5" />
                  ) : (
                    <ArrowUpRight className="w-5 h-5" />
                  )}
                </div>
                <div className="flex-1">
                  <p className="text-sm font-bold text-white">{tx.desc}</p>
                  <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-1 mt-1">
                    <Clock className="w-3 h-3" /> {tx.date}
                  </p>
                </div>
                <div className="text-right">
                  <p
                    className={clsx(
                      'text-sm font-black',
                      tx.type === 'EARNING' ? 'text-emerald-500' : 'text-white',
                    )}
                  >
                    {tx.type === 'EARNING' ? '+' : ''}RD$
                    {Math.abs(tx.amount).toLocaleString()}
                  </p>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </section>
  );
};

export default WalletTab;","path":"apps/driver/components/dashboard/WalletTab.tsx"}

{"content":"// apps/driver/components/dashboard/DriverShell.tsx
/**
 * DriverShell — Shell orquestador del Driver Portal con 4 tabs internos.
 *
 * ARQUITECTURA:
 *  - Los hooks (useTelemetry, useDriverHub, usePaymentStore) viven en
 *    pages/driver/dashboard.tsx y se pasan como props a este shell.
 *  - El shell gestiona el estado del tab activo (useState).
 *  - Los tabs cambian SOLO el JSX del <main>, lo que significa que los hooks
 *    del dashboard NO se desmontan (startTracking/stopTracking no se re-envocan).
 *  - La BottomNavigationBar se renderiza a nivel shell, no por página.
 *
 * Z-INDEX MAP:
 *  30 — BottomNavigationBar
 *  40 — StatusBar (header, ya existente)
 *  95 — DriverOnboardingModal
 * 100 — LockdownScreen
 */
'use client';

import React, { useState, useCallback } from 'react';
import { BottomNavigationBar, type DriverTab } from './BottomNavigationBar';
import { RoutesTab } from './RoutesTab';
import { SettingsTab } from './SettingsTab';
import { WalletTab } from './WalletTab';
import {
  DriverWalletCard,
  DriverWalletCardSkeleton,
  GrowthCenter,
} from './GrowthCenter';
import { PulseDot } from '../../pages/driver/dashboard-utils';
import type { WalletState } from './DriverWalletCard';
import type { DriverHubData } from '../../hooks/useDriverHub';
import type { usePaymentStore } from '../../store/usePaymentStore';

// ─── Types ───────────────────────────────────────────────────────────────────
type ConnectionStatus = 'online' | 'offline' | 'syncing';

interface DriverShellProps {
  // Telemetría (useTelemetry)
  connectionStatus: ConnectionStatus;
  batchCount: number;
  offlineCount: number;
  isTracking: boolean;
  syncPending: () => Promise<{ processed: number; remaining: number; success: boolean }>;
  startTracking: () => void;
  stopTracking: () => void;
  // Hub
  hubData: DriverHubData | null;
  hubLoading: boolean;
  isLocalMode: boolean;
  refreshHub: () => Promise<void>;
  // Wallet card state
  walletState: WalletState | null;
  // Payment store
  isLocked: boolean;
  lockMessage: string | null;
  setLock: (locked: boolean, message?: string | null) => void;
  // Onboarding
  showOnboarding: boolean;
  bankPendingSync: boolean;
  onOpenOnboarding: () => void;
  // Actions
  onSupport: () => void;
  onReportFalla: () => void;
  onReferir: () => void;
  onLogout: () => void;
  // Sync
  syncingNow: boolean;
  onSincronizar: () => void;
  // Readiness card (children injected from parent)
  readinessCard?: React.ReactNode;
  onboardingModal?: React.ReactNode;
  lockdownScreen?: React.ReactNode;
}

// ─── EarningsLedger (inline, moved from dashboard.tsx) ─────────────────────────
function EarningsLedger({
  current,
  max,
  slotsUsed,
  totalSlots,
}: {
  current: number;
  max: number;
  slotsUsed: number;
  totalSlots: number;
}) {
  const pctIncome = max > 0 ? Math.min(100, Math.round((current / max) * 100)) : 0;
  const pctSlots = totalSlots > 0 ? Math.min(100, Math.round((slotsUsed / totalSlots) * 100)) : 0;
  const pct = Math.max(pctIncome, pctSlots);
  const remaining = Math.max(0, max - current);
  const filledSlots = Math.max(0, Math.min(totalSlots, slotsUsed));

  return (
    <section
      className="bg-[#0a0a0a] border-2 border-neutral-900 p-5"
      aria-label="Ledger de Ganancias"
    >
      <p className="text-neutral-500 text-[10px] font-black uppercase tracking-widest mb-1">
        Ganancias del Mes
      </p>
      <p
        className="text-white font-black tracking-tighter font-mono leading-none"
        style={{ fontSize: 'clamp(2.5rem, 10vw, 3.5rem)' }}
      >
        RD${current.toLocaleString('es-DO')}
      </p>
      <div className="flex items-center justify-between mt-1 mb-4">
        <span className="text-neutral-500 text-xs">
          Tope: <strong className="text-neutral-300">RD${max.toLocaleString('es-DO')}</strong>
          <span className="text-neutral-700 ml-1">({totalSlots} slots max)</span>
        </span>
        <span className="text-neutral-500 text-xs">
          Slots: <strong className="text-[#FFD400]">{slotsUsed}/{totalSlots}</strong>
        </span>
      </div>
      <div
        className="w-full h-3 bg-neutral-900 border border-neutral-800 overflow-hidden"
        role="progressbar"
        aria-valuenow={pctIncome}
        aria-valuemin={0}
        aria-valuemax={100}
      >
        <div
          className="h-full bg-[#FFD400] transition-all duration-700 ease-out"
          style={{ width: `${pctIncome}%` }}
        />
      </div>
      <div className="mt-2 w-full h-2 bg-neutral-900 border border-neutral-800 overflow-hidden" aria-hidden="true">
        <div
          className="h-full bg-[#f97316] transition-all duration-700 ease-out"
          style={{ width: `${pctSlots}%` }}
        />
      </div>
      <div className="flex gap-1 mt-3" aria-hidden="true">
        {Array.from({ length: totalSlots }).map((_, i) => (
          <div
            key={i}
            className="flex-1 h-1.5"
            style={{ backgroundColor: i < filledSlots ? '#FFD400' : '#262626' }}
          />
        ))}
      </div>
      <div className="flex justify-between mt-1">
        <span className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest">0 slots</span>
        <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">
          Ingresos {pctIncome}% · Slots {filledSlots}/{totalSlots}
        </span>
        <span className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest">{totalSlots} slots</span>
      </div>
      <p className="text-[10px] text-neutral-500 font-semibold mt-2">
        Faltan <span className="text-[#FFD400]">RD${remaining.toLocaleString('es-DO')}</span> para RD${max.toLocaleString('es-DO')}
      </p>
    </section>
  );
}

// ─── HomeTab (inline) — El contenido principal del dashboard migrado ──────────
function HomeTab({
  hubData,
  hubLoading,
  isLocalMode,
  walletState,
  connectionStatus,
  bankPendingSync,
  onOpenOnboarding,
  readinessCard,
}: {
  hubData: DriverHubData | null;
  hubLoading: boolean;
  isLocalMode: boolean;
  walletState: WalletState | null;
  connectionStatus: ConnectionStatus;
  bankPendingSync: boolean;
  onOpenOnboarding: () => void;
  readinessCard?: React.ReactNode;
}) {
  const serviceBannerConfig =
    connectionStatus === 'offline'
      ? { label: 'MODO OFFLINE: Guardando local y reintentando en segundo plano', color: '#f97316', bg: '#2a1405', border: '#ea580c' }
      : connectionStatus === 'syncing'
        ? { label: 'SINCRONIZANDO TELEMETRÍA...', color: '#FFD400', bg: '#1a1400', border: '#FFD400' }
        : { label: 'SERVICIO ACTIVO: PUBLICIDAD EN CURSO', color: '#22c55e', bg: '#052e16', border: '#16a34a' };

  return (
    <div className="space-y-5">
      {isLocalMode && (
        <div className="rounded-2xl border border-amber-300/40 bg-amber-500/10 backdrop-blur-md px-4 py-3" role="status" aria-live="polite">
          <p className="text-xs font-black tracking-wide text-amber-200">⚠️ Operando en Modo Local (Red Inestable)</p>
        </div>
      )}

      {/* Service Status Banner */}
      <div
        className="flex items-center justify-center gap-2 py-2.5 px-3 border"
        style={{ backgroundColor: serviceBannerConfig.bg, borderColor: serviceBannerConfig.border }}
        role="status"
        aria-live="polite"
      >
        <PulseDot color={serviceBannerConfig.color} />
        <span className="text-[10px] font-black uppercase tracking-widest" style={{ color: serviceBannerConfig.color }}>
          {serviceBannerConfig.label}
        </span>
      </div>

      {/* Readiness Card — injected from parent (exact same component as before) */}
      {readinessCard}

      {/* Wallet Card */}
      {walletState ? <DriverWalletCard wallet={walletState} /> : <DriverWalletCardSkeleton />}

      {/* Growth Center */}
      <GrowthCenter
        referralUrl={`/driver/onboarding?ref=${hubData?.driverId ?? 'tad500'}`}
        referralCode={hubData?.driverId ? `DRV-${hubData.driverId.slice(0, 6).toUpperCase()}` : 'DRV-TAD500'}
        onShare={() => {
          if (navigator.share) {
            navigator.share({
              title: 'Únete a TAD Driver',
              text: 'Gana hasta RD$7,500 al mes poniendo publicidad en tu taxi. Únete con mi enlace:',
              url: window.location.origin + '/driver/onboarding',
            }).catch(() => undefined);
          } else {
            window.open(
              `https://wa.me/?text=${encodeURIComponent('Gana hasta RD$7,500 al mes con TAD Driver: ' + window.location.origin + '/driver/onboarding')}`,
              '_blank',
              'noopener,noreferrer',
            );
          }
        }}
      />

      {/* Earnings Ledger */}
      <EarningsLedger
        current={walletState?.total ?? 0}
        max={7500}
        slotsUsed={hubData?.activeSlots ?? 0}
        totalSlots={hubData?.maxSlots ?? 15}
      />
    </div>
  );
}

// ─── DriverShell — Main Component ─────────────────────────────────────────────
export const DriverShell: React.FC<DriverShellProps> = ({
  connectionStatus,
  batchCount,
  offlineCount,
  isTracking,
  syncPending,
  hubData,
  hubLoading,
  isLocalMode,
  walletState,
  isLocked,
  readinessCard,
  onboardingModal,
  lockdownScreen,
  onSupport,
  onReportFalla,
  onReferir,
  onLogout,
  syncingNow,
  onSincronizar,
}) => {
  const [activeTab, setActiveTab] = useState<DriverTab>('home');

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white font-sans">
      {/* Header fijo con telemetría — StatusBar del dashboard original */}

      {/* Contenido principal con padding-top para header fijo + padding-bottom para bottom nav */}
      <main className="mx-auto max-w-md px-4 pt-20 pb-28" id="dashboard-main">
        {activeTab === 'home' && (
          <HomeTab
            hubData={hubData}
            hubLoading={hubLoading}
            isLocalMode={isLocalMode}
            walletState={walletState}
            connectionStatus={connectionStatus}
            bankPendingSync={false}
            onOpenOnboarding={() => {}}
            readinessCard={readinessCard}
          />
        )}

        {activeTab === 'routes' && (
          <RoutesTab
            connectionStatus={connectionStatus}
            batchCount={batchCount}
            offlineCount={offlineCount}
            isTracking={isTracking}
            onSync={onSincronizar}
            syncingNow={syncingNow}
          />
        )}

        {activeTab === 'wallet' && (
          <WalletTab
            hubData={hubData}
            connectionStatus={connectionStatus}
            walletState={walletState}
            isLocalMode={isLocalMode}
          />
        )}

        {activeTab === 'settings' && (
          <SettingsTab
            connectionStatus={connectionStatus}
            batchCount={batchCount}
            offlineCount={offlineCount}
            isTracking={isTracking}
            onSync={onSincronizar}
            onSupport={onSupport}
            onReportFalla={onReportFalla}
            onReferir={onReferir}
            onLogout={onLogout}
            syncingNow={syncingNow}
          />
        )}

        {/* Footer info (only on home tab) */}
        {activeTab === 'home' && (
          <footer className="pt-6 text-center space-y-2">
            <p className="text-neutral-700 text-[10px] font-bold uppercase tracking-widest">
              TAD DOOH Platform v12.0.0
            </p>
            <p className="text-neutral-800 text-[9px] font-mono">
              GPS: {isTracking ? 'ACTIVO' : 'INACTIVO'} · Batch: {batchCount}/10 · Red: {connectionStatus.toUpperCase()}
            </p>
            {process.env.NODE_ENV !== 'production' && (
              <button
                id="debug-trigger-402"
                onClick={() => {
                  // Import dynamically to avoid circular deps
                  import('../../store/usePaymentStore').then(({ usePaymentStore }) => {
                    usePaymentStore.getState().setLock(true, 'DEBUG: Suscripción vencida (402)');
                  });
                }}
                className="mt-2 text-neutral-800 text-[9px] uppercase font-bold border border-neutral-900 px-3 py-1 hover:text-red-900 transition-colors"
              >
                Debug: Forzar Bloqueo 402
              </button>
            )}
          </footer>
        )}
      </main>

      {/* Bottom Navigation Bar */}
      <BottomNavigationBar activeTab={activeTab} onChange={setActiveTab} />

      {/* Pantalla de Lockdown 402 */}
      {lockdownScreen}

      {/* Onboarding Modal */}
      {onboardingModal}
    </div>
  );
};

